import React from 'react';
import '../styles/Servicios.css';

const GestionTributaria = () => (
  <div className="servicios-container">
    <h2 className="servicios-title">Gestión Tributaria</h2>
    <p>Planificación y cumplimiento de obligaciones tributarias, optimización de impuestos y representación ante entidades fiscales.</p>
  </div>
);

export default GestionTributaria;
